cat > /tmp/verify/debug_search.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const logs = [];
    page.on('console', m => logs.push('[' + m.type() + '] ' + m.text()));
    page.on('pageerror', e => logs.push('[pageerror] ' + e.message));
    await page.goto('http://localhost/index.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(4000);
    await page.selectOption('#chooseIndex', { label: 'spotify_tracks' });
    await page.waitForTimeout(5000);
    await page.click('.oneCollapsibleItem.filter .collapsible-header');
    await page.waitForTimeout(1000);
    await page.selectOption('#dataExplorerDataFields', { index: 1 });
    await page.waitForTimeout(3000);
    await page.click('.oneCollapsibleItem.output .collapsible-header');
    await page.waitForTimeout(1000);
    await page.selectOption('.chartTypeChooser', { label: 'barChart' });
    await page.waitForTimeout(1500);
    const before = logs.length;
    await page.click('#getResults');
    await page.waitForTimeout(10000);
    const after = logs.slice(before).filter(l => !l.startsWith('[warning]'));
    console.log('--- CONSOLE AFTER getResults ---');
    after.forEach(l => console.log(l));
    const gw = await page.$eval('#graphicsWrapper', el => ({ htmlLen: el.innerHTML.length, snippet: el.innerHTML.slice(0, 400) })).catch(e => 'ERR ' + e.message);
    console.log('GRAPHICS_WRAPPER: ' + JSON.stringify(gw));
    const btnVisible = await page.$eval('#getResults', el => el.offsetParent !== null);
    console.log('button visible: ' + btnVisible);
    await browser.close();
})().catch(e => { console.error('DBG2_FAILED', e); process.exit(1); });
EOF
cd /tmp/verify && node debug_search.js 2>&1 | head -50
